<script setup>
import {computed,ref} from 'vue'
import {useRoute} from 'vue-router'
import ProductCard from '../components/ProductCard.vue'
import {shop,agregarCarrito,notificar} from '../stores/shop'
function agregarRapido(p){agregarCarrito(p.id,'M',p.colors[0][0],1);notificar(`${p.name} agregado (talla M)`)}
const route=useRoute(), categoria=ref(route.query.cat||'todo'), busqueda=ref(''), precio=ref('todos'), orden=ref('popular')
const soloOfertas=computed(()=>route.query.oferta==='1')
const rangos={todos:[0,Infinity],bajo:[0,39999],medio:[40000,80000],alto:[80001,Infinity]}
const filtrados=computed(()=>shop.productos.filter(p=>(!soloOfertas.value||(p.old&&p.old>p.price))&&(categoria.value==='todo'||p.cat===categoria.value)&&p.price>=rangos[precio.value][0]&&p.price<=rangos[precio.value][1]&&p.name.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').includes(busqueda.value.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,''))).sort(({sold:a,order:oa,price:pa},{sold:b,order:ob,price:pb})=>orden.value==='popular'?b-a:orden.value==='nuevos'?ob-oa:orden.value==='asc'?pa-pb:pb-pa))
</script>
<template><section class="view"><section class="shop"><header class="section-head"><h1>{{soloOfertas ? "Ofertas de la semana" : "Tienda"}}</h1><p>{{soloOfertas ? "Prendas seleccionadas con descuentos de hasta el 31%." : "Encuentra tu prenda favorita, elaborada con material de calidad."}}</p><RouterLink v-if="soloOfertas" class="btn btn--sm btn--soft" to="/tienda">Ver todo el catálogo</RouterLink></header><div class="filters"><fieldset class="chips"><legend class="sr-only">Categoría</legend><template v-for="c in [{v:'todo',t:'Todo'},{v:'tops',t:'Tops'},{v:'vestidos',t:'Vestidos'},{v:'conjuntos',t:'Conjuntos'},{v:'bottoms',t:'Pantalones y faldas'},{v:'abrigos',t:'Abrigos'}]" :key="c.v"><input :id="'cat-'+c.v" v-model="categoria" type="radio" name="cat" :value="c.v"><label :for="'cat-'+c.v">{{c.t}}</label></template></fieldset><div class="tools"><label>Buscar <input v-model="busqueda" type="search" placeholder="Nombre de la prenda"></label><label>Precio <select v-model="precio"><option value="todos">Todos</option><option value="bajo">Hasta $39.999</option><option value="medio">$40.000 - $80.000</option><option value="alto">Desde $80.001</option></select></label><label>Ordenar <select v-model="orden"><option value="popular">Más vendidos</option><option value="nuevos">Más nuevos</option><option value="asc">Menor precio</option><option value="desc">Mayor precio</option></select></label></div></div><p class="count">{{filtrados.length}} {{filtrados.length===1?'prenda encontrada':'prendas encontradas'}}</p><div v-if="filtrados.length" class="cards"><ProductCard v-for="p in filtrados" :key="p.id" :producto="p" @agregar="agregarRapido" /></div><p v-else class="empty-msg">No encontramos prendas con esos filtros. Prueba con otra categoría o precio.</p></section></section></template>
